function App() {
  const [draft, setDraft] = React.useState("");
  const [saved, setSaved] = React.useState("");
  const [count, setCount] = React.useState(0);
  function save(event) {
    event.preventDefault();
    setSaved(draft);
    setCount(value => value + 1);
  }
  return (
    <main>
      <form onSubmit={save}>
        <label htmlFor="entry">Entry</label>
        <input id="entry" value={draft} onChange={event => setDraft(event.target.value)} />
        <button type="submit">Save</button>
      </form>
      <p role="status">Saved: {saved}; count: {count}</p>
    </main>
  );
}
```
Each submission keeps the current draft and increases the count once.
